    case "osk":
      return "osk";
    case "tal":
      return "tal";
    case "vok":
      return "vok";
    case "zef":
      return "zef";
    default:
      return undefined;
  }
}

export const protocol: WorldProtocol<WorldState> = {
  reset(): WorldState {
    return createInitialWorld();
  },

  applyOperation(state, operationDisplayName) {
    const operation = operations[operationDisplayName];
    if (!operation) {
      return {
        success: false,
        error: `Unknown operation: ${operationDisplayName}`,
